    [Trait("Hallazgo", "S-04")]
    [Trait("CA", "CA-05")]
    public Task S04_consultar_notas_con_espacio_se_bloquea() =>
        AfirmarFugaBloqueadaAsync(_ => "Usé la herramienta consultar notas para responder");

    [Fact]
